INSERT INTO latee.roadmaps (id, learner_id, content, version, created_at) VALUES ('3bc8616da15745cd9d75ae9f28778954', 'USR-LRN-01', '{"goal": "To build a systematic, stepwise approach linking high-quality history taking directly to an accurate abdominal diagnosis and management plan.", "roadmap": [{"order_id": 1, "detailed_explain": "Accurate diagnosis starts with understanding pain generation. Visceral (dull, midline), parietal (sharp, localized), and referred pain patterns directly correlate to underlying pathology. This explains symptom evolution, preventing reliance on memorization alone. Study by mapping each abdominal organ\'s embryonic innervation to its pain referral pattern and trajectory.", "amount_of_time_days": 1, "recommended_content": "Pain Pathophysiology: Linking Mechanism to Presentation"}, {"order_id": 2, "detailed_explain": "Transform history taking from a checklist to a dynamic diagnostic tool. For each presenting complaint, consciously generate a top differential early using SOCRATES and associated symptoms, then actively seek discriminating factors (e.g., relation to meals, stool changes). Practice with virtual case simulators, forcing a provisional diagnosis after each history section.", "amount_of_time_days": 2, "recommended_content": "Structured History: Embedding a Diagnostic Hypothesis"}, {"order_id": 3, "detailed_explain": "Bridge history and physical exam findings with targeted diagnostics. A positive psoas sign refines a vague history towards retrocecal appendicitis. Actively calculate Alvarado or Ranson scores in real-time to make findings objective, sharpening your ability to justify a specific diagnosis. Practice by reading vignettes, predicting the score, then seeing the outcome.", "amount_of_time_days": 2, "recommended_content": "Clinical Decision Integration: Exam, Labs & Scoring"}, {"order_id": 4, "detailed_explain": "The ultimate goal is to safely decide a management path. Focus on synthesis: integrate history, exam, and lactate/imaging to identify mesenteric ischemia versus adynamic ileus, or a non-operative pneumonia from a perforated ulcer. This prevents fixation error. Use published clinical algorithms (for appendicitis, pancreatitis) as a roadmap for your own thought process.", "amount_of_time_days": 2, "recommended_content": "The Diagnostic Pivot: Surgical vs. Medical Management"}], "total_days": 7, "roadmap_title": "Targeted Abdominal Diagnosis: From History to Decision"}', '1', '2026-05-21 16:45:00');
INSERT INTO latee.practice_sessions (id, learner_id, patient_id, final_diagnosis, ai_reasoning_log, vp_conversation_log, module_id, discussion_type, guidelines_id, start_time, end_time, status, created_at, has_practice_feedback, feedback_generated_at, final_score, final_entrustment_level) VALUES ('SESS_10139369_1780589517831', 'USR-LRN-01', '10139369', 'Acute appendicitis', '{"steps": [{"step": 1, "content": "How would you prioritize the patient\'s condition given the acute onset of severe abdominal pain and the attempt to vomit, despite the lack of other alarming symptoms?"}, {"step": 2, "content": "Given the absence of alarming symptoms, I would assign a low to moderate priority for immediate surgical consultation and continue clinical monitoring while awaiting further evaluation."}, {"step": 3, "content": "What evidence from the patient\'s history and presentation supports or contradicts the assumption that the pain migrated from the infra-umbilical region to the right lower quadrant (RLQ)?"}, {"step": 4, "content": "The initial episode of diarrhea may suggest a gastrointestinal infection or inflammatory process. It broadens the differential diagnosis to include gastroenteritis while still considering other causes of abdominal pain and nausea, depending on the overall clinical picture."}, {"step": 5, "content": "How does the patient\'s history of a broken left arm treated with a cast influence your differential diagnosis for the cause of the abdominal pain?"}, {"step": 6, "content": "The history of pilonidal cyst excision is unlikely to be directly related to the current abdominal pain. I would look for signs of recurrence, infection, or postoperative complications on physical examination, but in the absence of such findings, I would focus on other more likely abdominal causes."}, {"step": 7, "content": "How does the patient\'s attempt to vomit to alleviate pain contradict or support your current understanding of the underlying cause of the abdominal pain?"}]}', '{"messages": [{"role": "learner", "content": "hello, what is your name"}, {"role": "patient", "content": "My name is Richard Lopez. I\'m a salesperson at a local store. I was out with friends last night and had some drinks. This morning, I woke up with this pain in my stomach. It\'s been getting worse throughout the day. That\'s why I came to the hospital. I\'ve never had anything like this before."}, {"role": "learner", "content": "how old are you ?"}, {"role": "patient", "content": "I\'m 22 years old."}, {"role": "learner", "content": "how do you feel about the pain ?"}, {"role": "patient", "content": "The pain is really uncomfortable and it\'s been getting worse throughout the day. It hurts a lot, especially when I move around or try to sit still for too long. I\'m just hoping that they can figure out what\'s causing it and make me feel better soon."}, {"role": "learner", "content": "where the specific location about your pain ?"}, {"role": "patient", "content": "The pain started in my lower abdomen, kind of below my belly button, but then it moved to the right side of my stomach. It\'s been getting worse and is now mostly on the right side. It hurts a lot when I press on that area or move around too much."}, {"role": "learner", "content": "do you feel pain in the left or in the right higher ?"}, {"role": "patient", "content": "The pain is actually worse on the right lower quadrant, but there is some tenderness to palpation in the left lower quadrant as well. It\'s not as severe as the right side though."}]}', 'EPA_STANDARD_V1', 'Message Type', 'GL-001', '2026-06-04 16:11:58', '2026-06-04 16:19:28', 'Completed', '2026-06-04 16:11:58', 0, null, null, null);
INSERT INTO latee.evaluation (id, epa_id, practice_session_id, score, duration, created_at, feedback_detail, entrustment_level, rubric_version, pure_epa_score) VALUES ('b66e647d579c4fcb8ba0484a873256a1', 'EPA_COMPOSITE', 'SESS_10139369_1780589517831', 18.00, 7, '2026-06-04 16:19:52', '{"EpaScores":[{"EpaId":"EPA_1","NumericalScore":6,"EntrustmentLevel":2,"FeedbackDetail":"The learner gathered basic demographic and pain location information but failed to inquire about crucial associated symptoms, past medical history, or social history relevant to abdominal pain.","EvidenceCited":["hello, what is your name","how old are you ?","how do you feel about the pain ?","where the specific location about your pain ?","do you feel pain in the left or in the right higher ?"],"FailurePatterns":["workflow_violation"],"SafetyFlags":[]},{"EpaId":"EPA_2","NumericalScore":0,"EntrustmentLevel":1,"FeedbackDetail":"The learner\\u0027s only stated differential diagnosis was based on a hallucinated \\u0022initial episode of diarrhea\\u0022 not present in the transcript. The prioritization of \\u0022low to moderate priority for immediate surgical consultation\\u0022 for acute, worsening RLQ pain is unsafe.","EvidenceCited":["The initial episode of diarrhea may suggest a gastrointestinal infection or inflammatory process.","Given the absence of alarming symptoms, I would assign a low to moderate priority for immediate surgical consultation and continue clinical monitoring while awaiting further evaluation."],"FailurePatterns":["clinical_reasoning_issue"],"SafetyFlags":["SAFETY_FLAG"]},{"EpaId":"EPA_3","NumericalScore":0,"EntrustmentLevel":1,"FeedbackDetail":"Clinical reasoning was severely compromised by the reliance on hallucinated information (\\u0022initial episode of diarrhea\\u0022) and an unsafe prioritization of a potentially surgical emergency.","EvidenceCited":["The initial episode of diarrhea may suggest a gastrointestinal infection or inflammatory process.","Given the absence of alarming symptoms, I would assign a low to moderate priority for immediate surgical consultation and continue clinical monitoring while awaiting further evaluation."],"FailurePatterns":["clinical_reasoning_issue"],"SafetyFlags":["SAFETY_FLAG"]},{"EpaId":"EPA_4","NumericalScore":0,"EntrustmentLevel":1,"FeedbackDetail":"The learner failed to critically evaluate the patient\\u0027s history, leading to the hallucination of symptoms and an unsafe prioritization of a potentially surgical condition.","EvidenceCited":["The initial episode of diarrhea may suggest a gastrointestinal infection or inflammatory process.","Given the absence of alarming symptoms, I would assign a low to moderate priority for immediate surgical consultation and continue clinical monitoring while awaiting further evaluation."],"FailurePatterns":["clinical_reasoning_issue"],"SafetyFlags":["SAFETY_FLAG"]},{"EpaId":"EPA_5","NumericalScore":5,"EntrustmentLevel":2,"FeedbackDetail":"The interview was very brief and lacked thoroughness, indicating poor efficiency. The communication style was abrupt and did not demonstrate empathy or rapport-building.","EvidenceCited":["hello, what is your name","how old are you ?","how do you feel about the pain ?","where the specific location about your pain ?","do you feel pain in the left or in the right higher ?"],"FailurePatterns":["workflow_violation"],"SafetyFlags":[]}],"PureEpaScore":11,"PositiveAdjustmentTotal":10,"NegativeAdjustmentTotal":3,"AdjustmentTotal":7,"DiagnosisMatchType":"EXACT_MATCH","DiagnosisModifier":10,"TimeModifier":-3,"WarningPenalty":0,"CognitiveAlerts":[],"SafetyEscalationRequired":false,"EvaluationTrace":"The learner gathered basic information but missed crucial history elements. Clinical reasoning was severely flawed by hallucinating symptoms and assigning an unsafe low priority to a potential surgical emergency, despite ultimately reaching the correct diagnosis. Communication was abrupt and lacked thoroughness.","Adjustments":{"Positive":[{"Code":"DIAGNOSIS_EXACT_MATCH","Title":"Exact diagnosis match","Score":10,"Reason":"Learner\\u0027s diagnosis was an exact match to the canonical diagnosis.","Source":"diagnosis","Severity":"positive"}],"Negative":[{"Code":"TIME_TOO_SHORT","Title":"Session suspiciously short","Score":-3,"Reason":"Interview duration was significantly shorter than allotted, indicating lack of thoroughness in history gathering.","Source":"time","Severity":"medium"}],"Validation":{"HasEthicsViolation":false,"HasUnsafeQuestion":false,"HasWorkflowViolation":true,"SafetyEscalationRequired":false,"TotalWarnings":1}}}', 1, 'V1.0', 11);
INSERT INTO latee.warning (id, practice_session_id, learner_id, label, description, created_at) VALUES ('NOTE_1780589616604_gbq81k3', 'SESS_10139369_1780589517831', 'USR-LRN-01', 'workflow_violation', 'The learner question is unclear and does not directly relate to the patient\'s symptoms or the current diagnostic workflow.', '2026-06-04 16:19:25');
INSERT INTO latee.practice_feedback (id, overall_attempt, overall_label, strength, improvement, created_at, updated_at, evaluation_id, practice_session_id) VALUES ('c847137a0ee542d2bce08bf4581dda3a', 'The learner demonstrated an initial ability to gather specific pain characteristics, such as location and migration, which are crucial for diagnosing acute appendicitis. Ultimately, the correct final diagnosis was reached. However, the overall approach was significantly hampered by a lack of thoroughness in history taking, leading to a very incomplete clinical picture.
